+      final run = agent.run();
+      io.sendLine('start the detour');
+      await waitForIt(
+        () => stream.calls >= 2 && !agent.isBusy,
+        reason: 'run 1 created the checkpoint',
+      );
+      io.sendLine('any luck?');
+      await waitForIt(
+        () => stream.calls >= 3 && !agent.isBusy,
+        reason: 'run 2 landed the real user turn inside the detour scope',
+      );
