+  test(
+    'AC4 no-op: an auto-close UNDER the trigger compacts nothing — the '
+    'existing behavior is preserved for healthy sessions',
+    timeout: const Timeout(Duration(minutes: 5)),
+    () async {
+      env.writeFile('big.txt', 'tiny\n');
+      final stream = FakeStreamFunction([
+        toolTurn([
+          const ToolCall(
+            id: 'c1',
+            name: 'checkpoint',
+            arguments: {'goal': 'detour'},
+          ),
+        ]),
+        textTurn('detour started'),
+        textTurn('no findings yet'),
+        toolTurn([
+          const ToolCall(
+            id: 'c2',
+            name: 'checkpoint',
+            arguments: {'goal': 'close it out'},
+          ),
+        ]),
+        textTurn('final answer, no cap needed'),
+      ]);
+      final agent = cli(stream);
+
+      final run = agent.run();
+      io.sendLine('start the detour');
+      await waitForIt(
+        () => stream.calls >= 2 && !agent.isBusy,
+        reason: 'run 1 created the checkpoint',
+      );
+      io.sendLine('any luck?');
+      await waitForIt(
+        () => stream.calls >= 3 && !agent.isBusy,
+        reason: 'run 2 settled',
+      );
+      io.sendLine('wrap it up');
+      await waitForIt(
+        () => stream.calls >= 5 && !agent.isBusy,
+        reason: 'run 3: the stale checkpoint auto-closed under the trigger',
+      );
+      io.sendLine('/exit');
+      await run;
+
+      final output = io.out.toString();
+      // The guard stayed out of the way: no cap receipt, no summarizer
+      // call between the auto-close and the final answer.
+      expect(output, isNot(contains('[checkpoint]')));
+      expect(stream.calls, 5);
+      expect(output, contains('final answer, no cap needed'));
+    },
+  );
+}
+
+/// A [FakeStreamFunction] that replays its LAST turn when the script runs
+/// dry: a forced compaction pass legitimately issues a variable number of
+/// LLM calls (chunked summarization prices the payload at the request
+/// size, so an over-trigger transcript is multi-chunk by construction),
+/// and the memory-extraction hook may add one more. The scripted prefix
+/// stays exact; only the overflow repeats the final-answer turn.
+class _CyclingStreamFunction extends FakeStreamFunction {
+  _CyclingStreamFunction(super.turns);
+
+  List<AssistantMessageEvent>? _last;
+
+  @override
+  AssistantMessageEventStream call(
+    Model model,
+    Context context, {
+    CancelToken? cancelToken,
+  }) {
+    if (turns.isNotEmpty) {
+      _last = turns.first;
+    } else if (_last != null) {
+      turns.add(_last!);
+    }
+    return super.call(model, context, cancelToken: cancelToken);
+  }
+}
