+/// addresses. Returns the JSONL text.
+String _marathonJsonl() {
+  const iso = '2026-01-01T00:00:00.000Z';
+  const count = 1200;
+  const boundary = 450;
+  final buffer = StringBuffer(
+    '{"type":"session","version":3,"id":"marathon","timestamp":"$iso",'
+    '"cwd":"/work"}\n',
+  );
