+        '"timestamp":"$iso","firstRecordId":"e470","lastRecordId":"e529",'
+        '"text":"checkpoint one: early tail work",'
+        '"coversRecordIds":['
+        '${[for (var j = 470; j <= 529; j++) '"e$j"'].join(',')}],'
+        '"flattenedRecordIds":[]}\n',
