      await _sink.persistMessage(messages[i]);
    }
    entryId = await session.appendCheckpoint(messageCount: count, goal: goal);
  }
  _active = CheckpointState(
    messageCount: count,
    entryId: entryId,
    startedAt: DateTime.now(),
    goal: goal,
  );
}

