+      UserMessage() => 'user:${_flat(m.content)}',
+      AssistantMessage() =>
+        'assistant:${m.content.whereType<TextContent>().map((b) => b.text).join('|')}',
+      ToolResultMessage(:final toolCallId) => 'tool:$toolCallId',
+      _ => m.runtimeType.toString(),
