+  for (var i = 0; i < count; i++) {
+    if (i == boundary) {
+      buffer.write(
+        '{"type":"compaction","id":"c$i","parentId":"e${i - 1}",'
+        '"timestamp":"$iso","summary":"earlier marathon context",'
+        '"firstKeptEntryId":"e0","tokensBefore":99999}\n',
+      );
+    }
+    buffer.write(
