+            : i == boundary
+            ? '"c$i"'
+            // The fold records chain off the live leaf when appended (the
+            // leaf moves to each fold record); the next message parents on
+            // the last fold record so the folds sit ON the active branch.
+            : i == 600
+            ? '"cc603"'
