  final hidden = <String>{};
  final checkpoints = <CompactCheckpointRecord>[];
  final covered = <String, CompactCheckpointRecord>{};
  final pinnedIds = <String>{};
  final dropped = <DroppedFold>[];
  void apply(
    SessionRecord record,
    bool emptyShape,
    void Function() applyEffect,
