+      // (the engine's real order): two hidden ranges + two nested
+      // checkpoints covering e470..e579.
+      buffer.write(
+        '{"type":"hidden_range","id":"h600","parentId":"e599",'
+        '"timestamp":"$iso","recordIds":['
+        '${[for (var j = 470; j <= 529; j++) '"e$j"'].join(',')}]}\n',
