+      buffer.write(
+        '{"type":"compact_checkpoint","id":"cc603","parentId":"h602",'
+        '"timestamp":"$iso","firstRecordId":"e470","lastRecordId":"e579",'
+        '"text":"checkpoint two: the whole folded tail",'
+        '"coversRecordIds":['
+        '${[for (var j = 470; j <= 579; j++) '"e$j"'].join(',')}],'
+        '"flattenedRecordIds":["cc601"]}\n',
