        break;
    }
  }
  return ResolvedFolds(
    state: StructuredViewState._(
      hiddenRecordIds: hidden,
      checkpoints: checkpoints,
      coveredRecordIds: covered,
      pinnedRecordIds: pinnedIds,
    ),
    dropped: dropped,
  );
}

