    switch (event) {
      case ToolExecutionStartEvent(:final toolCallId):
        _state._pendingToolCalls.add(toolCallId);
      case ToolExecutionEndEvent(:final toolCallId):
        _state._pendingToolCalls.remove(toolCallId);
