        context: _createContextSnapshot(),
        config: _createLoopConfig(
          skipInitialSteeringPoll: skipInitialSteeringPoll,
        ),
        emit: _processEvent,
        streamFunction: streamFunction,
        toolExecutor: toolExecutor,
        cancelToken: token,
      );
    });
